  '245-619': { severity: 'danger', description: 'Рифампицин снижает AUC ивосиденибав примерно на 92%. Комбинация противопоказана.' },
  // Вориностат + варфарин
  '21-621': { severity: 'warning', description: 'Вориностат усиливает антикоагулянтный эффект варфарина (механизм неизвестен). Частый мониторинг МНО в первые 4–8 нед совместного приёма.' },
  // Энкорафениб + кларитромицин
  '46-599': { severity: 'warning', description: 'Кларитромицин повышает концентрацию энкорафениба (CYP3A4). Снизить дозу энкорафениба при вынужденной комбинации; мониторинг нарушений зрения и QTc.' },
  // Энкорафениб + рифампицин
  '245-599': { severity: 'danger', description: 'Рифампицин снижает AUC энкорафениба примерно на 80% (CYP3A4 индукция). Комбинация противопоказана.' },
  // Вемурафениб + варфарин
  '21-602': { severity: 'warning', description: 'Вемурафениб ингибирует CYP2C9 — повышает концентрацию варфарина и риск кровотечения. Частый мониторинг МНО в первые 4 нед; возможно снижение дозы варфарина на 20–30%.' },
  // Вемурафениб + кларитромицин
  '46-602': { severity: 'warning', description: 'Кларитромицин повышает уровень вемурафениба (CYP3A4) + аддитивное удлинение QTc. Мониторинг ЭКГ; при QTc >500 мс — приостановить вемурафениб.' },
  // Вемурафениб + рифампицин
  '245-602': { severity: 'danger', description: 'Рифампицин снижает AUC вемурафениба. Комбинация не рекомендована — потеря противоопухолевого эффекта.' },
  // Вандетаниб + кларитромицин
  '46-605': { severity: 'danger', description: 'Кларитромицин + вандетаниб: мощное аддитивное удлинение QTc (оба препарата пролонгируют QT). Комбинация противопоказана — риск torsades de pointes / ФЖ.' },
  // Вандетаниб + рифампицин
  '245-605': { severity: 'danger', description: 'Рифампицин снижает AUC вандетаниба примерно на 40% (CYP3A4). Следует избегать — снижение эффективности при высоком риске токсичности.' },
  // Ларотрептиниб + кларитромицин
  '46-606': { severity: 'warning', description: 'Кларитромицин повышает концентрацию ларотрептиниба (CYP3A4 ингибирование). Снизить дозу вдвое (до 50 мг 2 раза/сут) при вынужденной комбинации.' },
  // Ларотрептиниб + рифампицин
  '245-606': { severity: 'danger', description: 'Рифампицин снижает AUC ларотрептиниба примерно на 71%. Комбинация противопоказана.' },
